SELECT FROM delivery WHERE buyer_tenant_id = #{tenantId} AND is_deleted = 0
AND status IN #{s}
AND (delivery_no LIKE CONCAT('%', #{keyword}, '%') OR ship_tracking_no LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM delivery WHERE buyer_tenant_id = #{tenantId} AND is_deleted = 0
AND status IN #{s}
AND (delivery_no LIKE CONCAT('%', #{keyword}, '%') OR ship_tracking_no LIKE CONCAT('%', #{keyword}, '%'))

SELECT FROM delivery WHERE supplier_tenant_id = #{tenantId} AND is_deleted = 0
AND status IN #{s}
AND (delivery_no LIKE CONCAT('%', #{keyword}, '%') OR ship_tracking_no LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY create_time DESC LIMIT #{offset}, #{limit}

