AND status IN #{s}
AND (delivery_no LIKE CONCAT('%', #{keyword}, '%') OR ship_tracking_no LIKE CONCAT('%', #{keyword}, '%'))

mapper.update:
UPDATE delivery
SET status = 'accepted', accept_result = 'accepted',
    accept_time = NOW(), accept_remark = #{acceptRemark}, update_by = #{updateBy}
WHERE id = #{id} AND buyer_tenant_id = #{tenantId}
  AND status = 'received' AND is_deleted = 0

UPDATE delivery
SET status = 'return_confirmed', update_by = #{updateBy}
WHERE id = #{id} AND supplier_tenant_id = #{tenantId}
  AND status = 'return_pending' AND is_deleted = 0

UPDATE delivery
SET status = 'returned', update_by = #{updateBy}
WHERE id = #{id} AND supplier_tenant_id = #{tenantId}
  AND status = 'return_shipping' AND is_deleted = 0

UPDATE delivery
SET ship_company = #{shipCompany},
    ship_tracking_no = #{shipTrackingNo},
    update_by = #{updateBy}
WHERE id = #{id} AND supplier_tenant_id = #{tenantId}
  AND status = 'shipped' AND is_deleted = 0

