SELECT COALESCE(SUM(ship_qty), 0) FROM delivery
WHERE contract_id = #{contractId} AND id != #{excludeId}
  AND reship_from IS NULL AND ship_qty IS NOT NULL AND is_deleted = 0

SELECT FROM delivery WHERE contract_id IN
#{cid}
AND is_deleted = 0 ORDER BY contract_id ASC, batch_no ASC

SELECT contract_id AS contractId, COALESCE(SUM(CASE WHEN reship_from IS NULL THEN quantity END), 0) AS allocatedQty, COALESCE(MAX(CASE WHEN status = 'pending_shipment' AND reship_from IS NULL THEN quantity END), 0) AS maxPendingQty FROM delivery WHERE contract_id IN
#{cid}
AND is_deleted = 0 GROUP BY contract_id

